def extract_even(data):
    """
    Recursively removes odd numbers from a nested tuple structure.

    Args:
        data (tuple): A nested or flat tuple containing integers and/or other tuples.

    Returns:
        tuple: A new tuple with only even numbers and filtered nested tuples.
    """
    if not isinstance(data, tuple):
        raise TypeError("Input must be a tuple")

    def filter_even(item):
        if isinstance(item, tuple):
            # Recursively process nested tuples
            return tuple(filter_even(sub_item) for sub_item in item if isinstance(sub_item, (int, tuple)))
        elif isinstance(item, int):
            # Include only even integers
            return item if item % 2 == 0 else None
        else:
            # Ignore non-integer, non-tuple items
            return None

    # Apply the filter and remove None values
    return tuple(filter(lambda x: x is not None, (filter_even(element) for element in data)))

# Example usage and test
assert extract_even((4, 5, (7, 6, (2, 4)), 6, 8)) == (4, (6, (2, 4)), 6, 8)
